import sys

def solve(n):
    if n == 2:
        return "NO"

    half = n // 2
    even_sum = 0
    odd_sum = 0

    even_numbers = []
    odd_numbers = []

    # Fill the first half with even numbers
    for i in range(1, half + 1):
        even_numbers.append(2 * i)
        even_sum += 2 * i

    # Fill the second half with odd numbers
    for i in range(1, half + 1):
        odd_numbers.append(2 * i - 1)
        odd_sum += 2 * i - 1

    # If the sums are already equal, we are done
    if even_sum == odd_sum:
        return "YES", even_numbers + odd_numbers

    # If the sum of evens is greater, we need to adjust the last few elements
    if even_sum > odd_sum:
        diff = even_sum - odd_sum
        # Try to replace the largest even number with the next odd number
        for i in range(half - 1, -1, -1):
            if even_numbers[i] + 1 <= odd_numbers[-1]:
                even_numbers[i] += 1
                odd_sum += 1
                if even_sum == odd_sum:
                    return "YES", even_numbers + odd_numbers
            else:
                break

    # If the sum of odds is greater, we need to adjust the last few elements
    if odd_sum > even_sum:
        diff = odd_sum - even_sum
        # Try to replace the largest odd number with the next even number
        for i in range(half - 1, -1, -1):
            if odd_numbers[i] + 1 <= even_numbers[-1]:
                odd_numbers[i] += 1
                even_sum += 1
                if even_sum == odd_sum:
                    return "YES", even_numbers + odd_numbers
            else:
                break

    return "NO"

def main():
